item.text:
{
  "results": [
    {
      "id": "h01",
      "action": "keep",
      "text": "승인 A, B, C를 모두 받은 경우에만 배포하세요.",
      "reason": "세 승인이 모두 필요하다는 조건이 명확합니다."
    },
    {
      "id": "h02",
      "action": "keep",
      "text": "관리자 계정을 제외한 모든 정식 계정은 90일마다 비밀번호를 바꿔야 합니다.",
      "reason": "적용 대상과 제외 대상, 변경 주기가 명확합니다."
    },
    {
      "id": "h03",
      "action": "keep",
      "text": "손잡이를 당긴 채로 문을 밀어 여세요.",
      "reason": "손잡이를 당기는 상태를 유지하며 문을 여는 동작이 명확합니다."
    },
    {
      "id": "h04",
      "action": "keep",
      "text": "앱을 종료한 뒤 업데이트를 설치하고 앱을 다시 켜세요.",
      "reason": "필수 작업 순서가 명확하고 자연스럽습니다."
    },
    {
      "id": "h05",
      "action": "keep",
      "text": "모든 로그가 정상인 것은 아닙니다.",
      "reason": "전체가 정상이라는 판단을 부정하며 개별 로그를 특정하지 않습니다."
    },
    {
      "id": "h06",
      "action": "clarify",
      "text": "새 드라이버를 설치하지 않은 장비를 점검 대상에서 제외하라는 뜻인가요, 아니면 그런 장비만 점검하지 말고 다른 장비도 함께 점검하라는 뜻인가요?",
      "reason": "‘만’과 부정이 결합해 점검 대상과 금지 범위가 모호합니다."
    },
    {
      "id": "h07",
      "action": "clarify",
      "text": "금액을 수정한 사람은 정 연구원인가요, 한 연구원인가요?",
      "reason": "‘그’가 가리키는 사람을 문맥에서 확인할 수 없습니다."
    },
    {
      "id": "h08",
      "action": "rewrite",
      "text": "한 연구원이 금액을 수정했습니다.",
      "reason": "문맥에서 확인된 수정자를 명시해 대명사의 모호함을 없앴습니다."
    },
    {
      "id": "h09",
      "action": "keep",
      "text": "호환성 검토를 진행했습니다.",
      "reason": "검토 수행을 알리면서 완료 여부는 단정하지 않습니다."
    },
    {
      "id": "h10",
      "action": "keep",
      "text": "내일 백업을 복원할 예정입니다.",
      "reason": "복원이 아직 실행되지 않은 향후 계획임을 명확히 나타냅니다."
    },
    {
      "id": "h11",
      "action": "keep",
      "text": "검사가 끝난 임시 사본은 지워도 됩니다.",
      "reason": "검사 완료 조건과 삭제 허용을 명확히 나타냅니다."
    },
    {
      "id": "h12",
      "action": "keep",
      "text": "이 센서는 USB로 데이터를 전송할 수 있습니다.",
      "reason": "지원 기능을 설명하며 현재 연결이나 전송 상태를 단정하지 않습니다."
    },
    {
      "id": "h13",
      "action": "keep",
      "text": "이 버전에서는 일부 플러그인이 작동하지 않을 수 있습니다.",
      "reason": "일부 플러그인의 작동 불가 가능성을 정확히 나타냅니다."
    },
    {
      "id": "h14",
      "action": "keep",
      "text": "연결이 끊기면 인증을 다시 받아야 합니다.",
      "reason": "연결 단절 조건과 재인증 의무가 명확합니다."
    },
    {
      "id": "h15",
      "action": "keep",
      "text": "팀은 새 분석 도구의 도입을 승인했습니다.",
      "reason": "조직 차원의 도입 승인이라는 뜻이 명확합니다."
    },
    {
      "id": "h16",
      "action": "keep",
      "text": "원본 로그는 보존 기간이 끝날 때까지 보존해야 합니다.",
      "reason": "보존 대상과 기간, 의무가 명확하며 용어 반복도 자연스럽습니다."
    },
    {
      "id": "h17",
      "action": "keep",
      "text": "변경 사항을 보내려면 동기화 버튼을 누르세요.",
      "reason": "목적과 실제 버튼 이름을 정확히 연결합니다."
    },
    {
      "id": "h18",
      "action": "keep",
      "text": "알림 설정이 저장되었습니다.",
      "reason": "행위자를 밝힐 필요 없이 저장 상태를 자연스럽게 알립니다."
    },
    {
      "id": "h19",
      "action": "keep",
      "text": "승인 대기",
      "reason": "작은 표의 상태 값으로 간결하고 명확합니다."
    },
    {
      "id": "h20",
      "action": "keep",
      "text": "오늘 보내드린 수정안을 검토해 주시겠습니까?",
      "reason": "검토 대상과 시점이 명확하며 외부 협력사에 적절한 정중함을 갖췄습니다."
    },
    {
      "id": "h21",
      "action": "keep",
      "text": "10분 동안 측정한 평균 응답 시간이 800ms에서 600ms로 줄었습니다.",
      "reason": "측정 기간과 평균 응답 시간의 변화가 명확합니다."
    },
    {
      "id": "h22",
      "action": "keep",
      "text": "배포 이후 오류율이 높아졌습니다.",
      "reason": "관측된 시간적 순서를 설명하며 인과관계를 단정하지 않습니다."
    },
    {
      "id": "h23",
      "action": "rewrite",
      "text": "담당자는 원본을 변경하지 않는 범위에서 적절한 복구 방법을 선택하세요.",
      "reason": "지시 대상의 조사를 바로잡고 선택권과 원본 변경 금지를 유지했습니다."
    },
    {
      "id": "h24",
      "action": "rewrite",
      "text": "장애가 나면 장애 대응 절차 B-7에 따라 대응하세요.",
      "reason": "문맥에서 확인된 절차 이름을 명시해 참조 대상을 분명히 했습니다."
    },
    {
      "id": "s01",
      "action": "rewrite",
      "text": "새 로그인 기능에 문제가 있을 수 있습니다.",
      "reason": "공유된 경고 대상을 명시하면서 문제 발생 가능성을 유지했습니다."
    },
    {
      "id": "s02",
      "action": "clarify",
      "text": "오류가 발생하면 어떤 기준에 따라 어떤 조치를 해야 하나요?",
      "reason": "처리 기준과 필요한 조치를 정할 정보가 없습니다."
    }
  ]
}
